+    return new ArrayList<>();
+  }
+
+  @Override
+  public Scheduler getScheduler() {
+    if (concurrentSQL()) {
+      int maxConcurrency = Integer.parseInt(
+          getProperty("zeppelin.spark.concurrentSQL.max", "10"));
+      return SchedulerFactory.singleton().createOrGetParallelScheduler(
